sys_script_include.script:
var EventUtils = Class.create();
EventUtils.prototype = {
    initialize: function() {
    },

    // a. Fetch all event details by event ID.
    getEventByID: function(eventID) {
        var event_gr = new GlideRecord('x_1790116_event_ma_event');
        event_gr.addQuery('number', eventID);
        event_gr.query();
        if (event_gr.next()) {
            return event_gr.u_event_name + ' | ' + event_gr.u_event_date + ' | ' + event_gr.u_location;
        }
        return 'No event found';
    },

    // b. Check if an event is VIP.
    isVIPEvent: function(eventID) {
        var event_gr = new GlideRecord('x_1790116_event_ma_event');
        event_gr.addQuery('number', eventID);
        event_gr.query();
        if (event_gr.next() && event_gr.u_vip == true) {
            return 'VIP Event';
        }
        return 'Not a VIP Event';
    },

    // // c. Calculate the remaining budget for an event.
    // calculateRemainingBudget: function(eventID) {
    //     var event_gr = new GlideRecord('x_1790116_event_ma_budget');
    //     event_gr.addQuery('number', eventID);
    //     event_gr.query();
    //     if (event_gr.next()) {
    //         var total = parseFloat(event_gr.u_total_budget || 0);
    //         var spent = 0;

    //         var exp = new GlideAggregate('x_1790116_event_ma_event_expense');
    //         exp.addQuery('u_event_id.number', eventID);
    //         exp.addAggregate('SUM', 'u_amount');
    //         exp.query();
    //         if (exp.next()) {
    //             spent = parseFloat(exp.getAggregate('SUM', 'u_amount') || 0);
    //         }

    //         var remaining = total - spent;
    //         return 'Remaining Budget: ' + event_gr.u_amount_remaining;
    //     }
    //     return 'Event not found';
    // },

    // d. Fetch event tasks.
    fetchEventTasks: function(eventID) {
        var task = new GlideRecord('x_1790116_event_ma_task');
        task.addQuery('u_event_id.number', eventID);
        task.query();
        var result = [];
        while (task.next()) {
            result.push(task.number + ' | ' + task.u_task_name);
        }
        return result.length ? result.join('\n') : 'No tasks found';
    },

    // e. Fetch event attendees.
    fetchEventAttendees: function(eventID) {
        var att = new GlideRecord('x_1790116_event_ma_attendee');
        att.addQuery('u_event_id.number', eventID);
        att.query();
        var result = [];
        while (att.next()) {
            result.push(att.u_attendee_name + ' | ' + att.u_email);
        }
        return result.length ? result.join('\n') : 'No attendees found';
    },

    // f. Fetch event vendors.
    fetchEventVendors: function(eventID) {
        var ven = new GlideRecord('x_1790116_event_ma_vendor');
        ven.addQuery('u_event_id.number', eventID);
        ven.query();
        var result = [];
        while (ven.next()) {
            result.push(ven.u_vendor_name + ' | ' + ven.u_email );
        }
        return result.length ? result.join('\n') : 'No vendors found';
    },

    // g. Fetch event budget details.
    fetchEventBudgetDetails: function(eventID) {
        var bud = new GlideRecord('x_1790116_event_ma_budget');
        bud.addQuery('u_event_id.number', eventID);
        bud.query();
        var result = [];
        while (bud.next()) {
            result.push(bud.u_total_budget + ' | ' + bud.u_amount_spent + ' | ' + bud.u_amount_remaining);
        }
        return result.length ? result.join('\n') : 'No budget items found';
    },

    // h. Fetch event feedback.
    fetchEventFeedback: function(eventID) {
        var fb = new GlideRecord('x_1790116_event_ma_feedback');
        fb.addQuery('u_event_id.number', eventID);
        fb.query();
        var result = [];
        while (fb.next()) {
            result.push(fb.u_attendee_id + ': ' + fb.u_rating+ ': ' + fb.u_comments);
        }
        return result.length ? result.join('\n') : 'No feedback found';
    },

    type: 'EventUtils'
};
